import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import java.util.Map;

@Override
public void generateGraph(Graph<String, DefaultEdge> target, Map<String, String> resultMap) {
    if (resultMap == null || resultMap.size() < 2) {
        return;
    }

    // Assuming the map contains two partitions, we split them into two sets
    int mid = resultMap.size() / 2;
    var keys = resultMap.keySet().iterator();

    var firstPartition = new java.util.ArrayList<String>();
    var secondPartition = new java.util.ArrayList<String>();

    int count = 0;
    while (keys.hasNext()) {
        String key = keys.next();
        if (count < mid) {
            firstPartition.add(key);
        } else {
            secondPartition.add(key);
        }
        count++;
    }

    // Add vertices to the graph
    for (String vertex : resultMap.values()) {
        target.addVertex(vertex);
    }

    // Connect each vertex in the first partition to each vertex in the second partition
    for (String v1 : firstPartition) {
        for (String v2 : secondPartition) {
            target.addEdge(v1, v2);
        }
    }
}

