private int popType(final String descriptor, int index, Stack<Object> outputFrameStack) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'D':
        case 'F':
        case 'I':
        case 'S':
        case 'Z':
            outputFrameStack.pop();
            index++;
            break;
        case 'J':
            outputFrameStack.pop(); // long occupies two stack slots
            outputFrameStack.pop();
            index++;
            break;
        case 'L': // Object type
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            outputFrameStack.pop();
            index++; // Skip ';'
            break;
        case '[': // Array type
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            if (descriptor.charAt(index) == 'L') {
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
            }
            outputFrameStack.pop();
            index++; // Skip last character of the array type
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

